def run_selftest():
    import io
    suite=unittest.TestSuite()
    for cls in (PolicyTests,TelegramTests,MultimodalTests):
        suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(cls))
    output=io.StringIO()
    result=unittest.TextTestRunner(stream=output,verbosity=2).run(suite)
    return {"tests":result.testsRun,"failures":len(result.failures),"errors":len(result.errors),"successful":result.wasSuccessful(),"details":output.getvalue()}

def speech_selftest():
    import boto3
    sample="I like learning English every day."
    result=boto3.client("polly").synthesize_speech(Engine="neural",VoiceId="Joanna",LanguageCode="en-US",OutputFormat="ogg_vorbis",Text=sample)
    with result["AudioStream"] as stream: audio=stream.read(2000000)
    text,confidence=transcribe_bytes(audio)
    reply,spoken=voice_feedback(text,confidence)
    return {"synthetic_transcript":text,"transcript_confidence":confidence,"playback_bytes":len(audio),"feedback":reply,"spoken":spoken}
